"""``workpeg ui serve --fake-cloud``: what the dev server builds, and what
it serves.

THE BUILD IS THE RELEASE'S

A page tested in dev mode has to be the page that ships. So dev mode builds
with exactly the arguments ``workpeg ui build`` uses, on start and on every
rebuild: the chrome from the CDN with the bundled copy as its fallback, icons
linked the way a release links them, the namespace the project declares. No
flag, and no environment variable (``WORKPEG_CHROME`` included), moves it, and
``build_ui`` takes no argument for dev mode at all. Plain ``serve`` on
localhost builds another way, for working on the SDK itself; a dev page does
not.

WHAT IS SERVED, AND NOTHING ELSE

The dev server answers on the developer's own origin, so whatever it serves
runs as the peg. It serves only what its last good build wrote, read off that
build when it finishes:

- the SDK's own files at the site root that the build left there,
  ``index.html`` among them. A build removes every one of them before it
  writes, so none is left from before it. One that something else writes
  into ``dist/`` while the build runs is named too: that is no more than
  writing over ``app.js``, which serving by name cannot stop either;
- the fonts it copied into ``fonts/``;
- the files it copied from ``public/``, judged again by the build's own rule,
  so a page or a script put there after the build is not among them;
- ``index.html`` for a path with no extension, except under ``/v1/``, which
  is the API's, and ``/_workpeg``, which is the dev server's.

Anything else is 404, even on disk: a file dropped into ``dist/`` by hand, a
copy an earlier build left behind, a served name turned into a link, or a
folder on the way to one, ``dist/`` itself included. Whatever reaches a
browser is a file in the folder the build wrote into, under the name it
wrote, with no link between that folder and it. The check and the read are
two steps, so a link made in between is not seen; whatever can do that can
write the bytes into ``dist/`` itself.

THE PAGE

``index.html`` is served with one change: the reload client's tag,
``<script src="/_workpeg_reload.js"></script>``, before ``</body>``, as plain
``serve`` adds it. Nothing else is added, no meta among it. The change is made
in the answer only and never written to disk: the page in ``dist/`` is byte for
byte the release's. The client is the SDK's own file, served from the installed
SDK on the page's own origin, so the script policy admits it as ``'self'``
with no new source.

WHO MAY ASK

Every request must name the dev install in ``Host``, exactly once, as
``<namespace>.dev.workpeg.com`` or that with ``:443``. Not ``localhost``, not
an IP, not another name: a page on some other name that resolves to this
computer (DNS rebinding) is refused before anything is read.
"""
from __future__ import annotations

import os
from pathlib import Path
from urllib.parse import unquote

from workpeg.ui import build

#: The answer to a request that does not name the dev install. Fixed words:
#: it never repeats what the request said.
HOST_REFUSED = "This dev server answers only at https://{domain}."
#: The answer to a request for a service worker's script, which a worker
#: installed by the dev server would outlive it with.
SERVICE_WORKER_REFUSED = "This dev server does not serve service workers."


def release_build(entry: "Path | str", out: "Path | str") -> Path:
    """Build *entry* into *out* exactly as ``workpeg ui build`` does."""
    return build.build_ui(str(entry), str(out), chrome_source="auto")


def host_allowed(values: "list[str]", domain: str) -> bool:
    """Whether a request's ``Host`` headers name *domain*, once, exactly:
    bare, as a browser sends it for https on 443, or with ``:443``."""
    from workpeg.ui.devmode import DEV_PORT

    return len(values) == 1 and values[0] in (domain, f"{domain}:{DEV_PORT}")


def _is_page_route(name: str) -> bool:
    """A path the page's own router answers: no extension, and not under
    the API's ``/v1/`` or the dev server's ``/_workpeg``."""
    first = name.split("/", 2)[1]
    return (not os.path.splitext(name)[1]
            and first != "v1" and not first.startswith("_workpeg"))


class DevSite:
    """What one dev server may serve: the files its last good build wrote."""

    def __init__(self, directory: "Path | str", entry: "Path | str") -> None:
        self.directory = Path(directory)
        self.entry = Path(entry)
        self.index = self.directory / "index.html"
        self._public = build._public_folder(self.entry)
        self._files: frozenset = frozenset()
        self._root = ""
        self.refresh()

    # ---------------------------------------------------------------- build

    def rebuild(self) -> None:
        """Build again, as a release would, and serve what that wrote. A
        build that fails raises before anything changes here, so the last
        good build goes on being served."""
        release_build(self.entry, self.directory)
        self.refresh()

    def refresh(self) -> None:
        """Read what the build that just finished wrote."""
        out = self.directory
        files = {"/" + name for name in build._sdk_names()
                 if build._is_lone_file(str(out / name))}
        # Every build copies every one of these, so none needs looking for.
        files |= {"/fonts/" + font.name for font in build._vendored_fonts()}
        files |= {"/" + "/".join(parts)
                  for path, parts in build._public_files(self._public)
                  if build._why_not_shippable(path, parts) is None}
        # Where the build wrote, as it was when the build finished. Read
        # again on each request, dist/ swapped for a link would serve the
        # folder behind it.
        self._root = os.path.realpath(out)
        self._files = frozenset(files)

    # ---------------------------------------------------------------- serve

    def resolve(self, path: str) -> "Path | None":
        """The file to answer *path* (query and fragment already cut) with,
        or None for a 404."""
        try:
            name = unquote(path, errors="strict")
        except UnicodeDecodeError:
            return None
        if not name.startswith("/"):
            return None
        if _is_page_route(name):
            name = "/index.html"
        if name not in self._files:
            return None
        parts = name[1:].split("/")
        found = self.directory.joinpath(*parts)
        # Looked at again now, not only at the build: a name the build wrote
        # that has since become a link would serve whatever it points at.
        if not build._is_lone_file(str(found)):
            return None
        # And the whole way to it, which the last step alone does not show:
        # dist/data made a link to a folder elsewhere serves what is there.
        # The way must be the build's own, not merely end under dist/: a
        # link to dist/dropped stays inside and still serves a file the
        # build never wrote. normcase because Windows' realpath gives the
        # case on disk.
        real = os.path.normcase(os.path.realpath(found))
        if real != os.path.normcase(os.path.join(self._root, *parts)):
            return None
        return found

    def page(self, content: bytes) -> bytes:
        """``index.html`` as it is served: the build's bytes with the reload
        client's tag before ``</body>``, and nothing else."""
        from workpeg.ui.serve import _add_reload_tag

        return _add_reload_tag(content)
